def normalize_number(text):
    """Normalize numbers to words"""
    text = str(text).strip()

    # Handle decimal numbers - convert each digit after decimal to words
    if re.match(r"^\d+\.\d+$", text):
        parts = text.split(".")
        whole_part = number_to_words_decimals(int(parts[0]))
        decimal_part = " ".join([digit_to_word(d) for d in parts[1]])
        return f"{whole_part} point {decimal_part}"

    # Handle integers with commas
    text_clean = text.replace(",", "")
    if re.match(r"^\d+$", text_clean):
        num = int(text_clean)
        return number_to_words_decimals(num)

    return text


def normalize_fraction(text):
    """Normalize fractions like 1/2, 1/4, 3/4"""
    text = str(text).strip().lower()

    # Common fractions
    fraction_map = {
        "1/2": "one half",
        "1/4": "one quarter",
        "3/4": "three quarters",
        "1/3": "one third",
        "2/3": "two thirds",
        "1/8": "one eighth",
        "3/8": "three eighths",
        "5/8": "five eighths",
        "7/8": "seven eighths",
        "1/6": "one sixth",
        "5/6": "five sixths",
        "1/5": "one fifth",
        "2/5": "two fifths",
        "3/5": "three fifths",
        "4/5": "four fifths",
        "1/10": "one tenth",
        "1/100": "one hundredth",
    }

    if text in fraction_map:
        return fraction_map[text]

    # Handle other fractions like 2/3, 5/7
    match = re.match(r"^(\d+)/(\d+)$", text)
    if match:
        numerator = int(match.group(1))
        denominator = int(match.group(2))
        # Common denominators
        denom_words = {
            2: "half" if numerator == 1 else "halves",
            3: "third" if numerator == 1 else "thirds",
            4: "quarter" if numerator == 1 else "quarters",
            5: "fifth" if numerator == 1 else "fifths",
            6: "sixth" if numerator == 1 else "sixths",
            7: "seventh" if numerator == 1 else "sevenths",
            8: "eighth" if numerator == 1 else "eighths",
            9: "ninth" if numerator == 1 else "ninths",
            10: "tenth" if numerator == 1 else "tenths",
        }
        if denominator in denom_words:
            return f"{number_to_words_decimals(numerator)} {denom_words[denominator]}"

    return text


def normalize_currency(text):
    """Normalize currency expressions"""
    text = str(text).strip()

    # Dollar amounts like $150 or $150.50
    match = re.match(r"^\$(\d+(?:\.\d{2})?)$", text)
    if match:
        amount = float(match.group(1))
        if amount == int(amount):
            return f"{number_to_words_decimals(int(amount))} dollars"
        else:
            dollars = int(amount)
            cents = int((amount - dollars) * 100)
            return f"{number_to_words_decimals(dollars)} dollars {number_to_words_decimals(cents)} cents"

    # Dollar amounts with "dollars" already
    if "dollar" in text.lower():
        return text

    return text


