def normalize_time(text):
    """Normalize time expressions"""
    text = str(text).strip()

    # Time like 12:47, 9:30am, 9:30 pm
    match = re.match(r"^(\d{1,2}):(\d{2})(am|pm)?$", text, re.IGNORECASE)
    if match:
        hour = int(match.group(1))
        minute = int(match.group(2))
        period = match.group(3).lower() if match.group(3) else ""

        if hour == 0:
            hour_str = "twelve"
        elif hour <= 12:
            hour_str = {
                1: "one",
                2: "two",
                3: "three",
                4: "four",
                5: "five",
                6: "six",
                7: "seven",
                8: "eight",
                9: "nine",
                10: "ten",
                11: "eleven",
                12: "twelve",
            }.get(hour, str(hour))
        else:
            hour_str = {
                13: "one",
