                15: "three",
                16: "four",
                17: "five",
                18: "six",
                19: "seven",
                20: "eight",
                21: "nine",
                22: "ten",
                23: "eleven",
                24: "twelve",
            }.get(hour, str(hour))

        if minute == 0:
            return f"{hour_str} o'clock" + (f" {period}" if period else "")
